CREATE TABLE IF NOT EXISTS "OWNER" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "OWNER_PHONE" (
	"phone" VARCHAR(20) NOT NULL,
	"owner_id" INTEGER
);

CREATE TABLE IF NOT EXISTS "PET" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100),
	"birth_date" DATE,
	"owner_id" INTEGER,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "VISIT" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"visit_no" INTEGER,
	"visit_date" TIMESTAMP,
	"total_amount" NUMERIC(10,2),
	"pet_id" INTEGER,
	"vet_id" INTEGER,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "VET" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "VET_SPECIALTY " (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"specialty_name" VARCHAR(100),
	"vet_id" INTEGER,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "SERVICE_ITEM" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"item_name" VARCHAR(100),
	"quantity" INTEGER,
	"price" NUMERIC(10,2),
	"visit_id" INTEGER,
	PRIMARY KEY("id")
);

ALTER TABLE "OWNER"
ADD FOREIGN KEY("id") REFERENCES "PET"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "PET"
ADD FOREIGN KEY("id") REFERENCES "VISIT"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "VISIT"
ADD FOREIGN KEY("id") REFERENCES "VET"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "VET"
ADD FOREIGN KEY("id") REFERENCES "VET_SPECIALTY "("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "VISIT"
ADD FOREIGN KEY("id") REFERENCES "SERVICE_ITEM"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "OWNER_PHONE"
ADD FOREIGN KEY("owner_id") REFERENCES "OWNER"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
